import { readFileSync } from "node:fs";
import type { APIRequestContext } from "@playwright/test";
import { expect, sample, test, uniqueName } from "../../fixtures";

async function upload(api: APIRequestContext, vendorId: string, kind: string, file: string) {
  const res = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: { kind, file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) } },
  });
  expect(res.status(), await res.text()).toBe(201);
  return (await res.json()) as { id: string };
}

async function inReviewVendor(member: APIRequestContext, name: string, insuranceFile: string): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: { name, category: "services", contact_email: "ops@northwind.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendorId = ((await created.json()) as { id: string }).id;

  await upload(member, vendorId, "w9", "w9.txt");
  await upload(member, vendorId, "contract", "contract.txt");
  await upload(member, vendorId, "insurance_certificate", insuranceFile);

  // Extraction runs in the background; wait until every document has been extracted.
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendorId}/documents`);
      const docs = (await res.json()) as { status: string }[];
      return docs.length === 3 && docs.every((d) => d.status === "extracted");
    }, { timeout: 30_000 })
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  return vendorId;
}

test("review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange: one vendor with an unparseable expiry date (lowest field 0.3), one fully parseable.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const shakyId = await inReviewVendor(member, uniqueName("Shaky Co"), "insurance_certificate_unparseable.txt");
  const confidentId = await inReviewVendor(member, uniqueName("Confident Co"), "insurance_certificate.txt");

  // Act
  let queue: { vendor_id: string; lowest_confidence: number }[] = [];
  await expect
    .poll(async () => {
      const res = await reviewer.get("/api/review-queue");
      expect(res.status(), await res.text()).toBe(200);
      queue = (await res.json()) as typeof queue;
      const ids = queue.map((i) => i.vendor_id);
      return ids.includes(shakyId) && ids.includes(confidentId);
    }, { timeout: 30_000 })
    .toBe(true);

  // Assert: the queue is ordered by lowest confidence ascending, and our shaky vendor precedes ours.
  const values = queue.map((i) => i.lowest_confidence);
  expect(values).toEqual([...values].sort((a, b) => a - b));
  const shaky = queue.find((i) => i.vendor_id === shakyId)!;
  const confident = queue.find((i) => i.vendor_id === confidentId)!;
  expect(queue.indexOf(shaky)).toBeLessThan(queue.indexOf(confident));
  expect(shaky.lowest_confidence).toBe(0.3);
  expect(shaky.lowest_confidence).toBeLessThan(confident.lowest_confidence);
});
